import{_ as a,D as s,c as d,j as o,a as e,I as c,a2 as r,o as n}from"./chunks/framework.DdOM6S6U.js";const y=JSON.parse('{"title":"CustomFormBase (v-custom-form-base)","description":"","frontmatter":{"sidebarPos":8,"sidebarTitle":"Custom Form Base (legacy)"},"headers":[],"relativePath":"guide/components/others/custom-form-base.md","filePath":"guide/components/others/custom-form-base.md","lastUpdated":1777448653000}'),i={name:"guide/components/others/custom-form-base.md"},m={id:"customformbase-v-custom-form-base",tabindex:"-1"},l=o("code",null,"v-custom-form-base",-1),h=o("a",{class:"header-anchor",href:"#customformbase-v-custom-form-base","aria-label":'Permalink to "CustomFormBase (`v-custom-form-base`) <Badge type="warning" text="legacy" />"'},"​",-1),u=r('<p><code>CustomFormBase</code> is the original self-contained schema-driven form engine. It implements the same <code>VFormBase</code> API as <a href="./form-base"><code>FormBase</code></a> but with all rendering logic and helper methods inline in the component rather than split into a composable and a sub-component.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><code>CustomFormBase</code> is kept for backwards compatibility. For new work use <a href="./form-base"><code>FormBase</code></a> (<code>v-form-base</code>), which is the refactored version with the same API.</p></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p><code>CustomFormBase</code> accepts exactly the same props, emits, schema syntax, slot naming convention, and supported field types as <code>FormBase</code>. Refer to the <a href="./form-base">FormBase documentation</a> for the complete reference.</p><p>Key differences from <code>FormBase</code>:</p><table><thead><tr><th>Aspect</th><th>FormBase</th><th>CustomFormBase</th></tr></thead><tbody><tr><td>Logic location</td><td><code>useFormBaseLogic</code> composable</td><td>Inline in the component&#39;s <code>methods</code> and <code>computed</code></td></tr><tr><td>Field rendering</td><td>Delegated to <code>FormBaseField</code></td><td>Inline <code>v-if/v-else-if</code> chain in the template</td></tr><tr><td>Composition API</td><td><code>setup</code> returns <code>ctx</code> from composable</td><td>Options API with <code>getCurrentInstance</code> in <code>setup</code></td></tr><tr><td>Nested self-reference</td><td><code>v-form-base</code></td><td><code>v-custom-form-base</code> (references itself recursively)</td></tr><tr><td>Schema rebuild trigger</td><td><code>watch</code> on <code>modelValue</code> keys via <code>__dot</code> + <code>onBeforeMount</code></td><td><code>watch</code> on <code>modelValue</code> keys via <code>__dot</code> in <code>created</code></td></tr></tbody></table><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use <code>CustomFormBase</code> only when:</p><ul><li>You are maintaining existing code that already imports <code>v-custom-form-base</code>.</li><li>You need to avoid a refactor risk in a critical path.</li></ul><p>In all other cases, use <code>FormBase</code>.</p>',10);function p(f,b,_,g,B,v){const t=s("Badge");return n(),d("div",null,[o("h1",m,[e("CustomFormBase ("),l,e(") "),c(t,{type:"warning",text:"legacy"}),e(),h]),u])}const w=a(i,[["render",p]]);export{y as __pageData,w as default};
